// Package imap implements a minimal RFC 3501 client behind the
// domain.InboundDialer port (the same port POP3 uses). It covers exactly what
// ingest needs — connect, LOGIN/PREAUTH, SELECT INBOX, enumerate (UID +
// RFC822.SIZE), fetch a message body, and mark-delete + EXPUNGE — and supports
// implicit TLS (993), STARTTLS, and plaintext for offline networks. Policy
// gating for insecure modes stays in the application layer.
package imap

import (
	"bufio"
	"bytes"
	"context"
	"crypto/tls"
	"errors"
	"fmt"
	"io"
	"math"
	"net"
	"regexp"
	"strconv"
	"strings"
	"time"

	"postra/internal/domain"
)

type Dialer struct{}

var (
	reFetch = regexp.MustCompile(`^\* (\d+) FETCH `)
	reUID   = regexp.MustCompile(`UID (\d+)`)
	reSize  = regexp.MustCompile(`RFC822\.SIZE (\d+)`)
	reExist = regexp.MustCompile(`^\* (\d+) EXISTS`)
	reValid = regexp.MustCompile(`UIDVALIDITY (\d+)`)
	reLit   = regexp.MustCompile(`\{(\d+)\}$`)
)

// errUnframed marks a session whose byte stream could no longer be put back in
// frame after a refused literal. Once it is set every command fails with it,
// which is the only safe answer: reading on would hand message bytes to the
// response parser.
var errUnframed = errors.New("imap session abandoned: response stream could not be resynchronized")

func (Dialer) Dial(ctx context.Context, opts domain.InboundDialOptions) (domain.InboundSession, error) {
	addr := net.JoinHostPort(opts.Host, strconv.Itoa(opts.Port))
	connectTO := secondsOr(opts.ConnectTimeoutSec, 15)
	d := &net.Dialer{Timeout: connectTO}
	tlsCfg := &tls.Config{
		ServerName: opts.Host,
		MinVersion: tls.VersionTLS12,
		// #nosec G402 -- offline/self-hosted IMAP servers may use self-signed
		// certs; skipping verification is an explicit per-account opt-in
		// (default false), required by offline-network mail support.
		InsecureSkipVerify: opts.InsecureSkipVerify,
	}

	var conn net.Conn
	var err error
	start := time.Now()
	switch opts.Security {
	case domain.SecurityTLS:
		conn, err = (&tls.Dialer{NetDialer: d, Config: tlsCfg}).DialContext(ctx, "tcp", addr)
	case domain.SecurityStartTLS, domain.SecurityNone:
		conn, err = d.DialContext(ctx, "tcp", addr)
	default:
		return nil, fmt.Errorf("unknown security mode %q", opts.Security)
	}
	if err != nil {
		return nil, connectFailure(err, time.Since(start), connectTO)
	}

	s := &session{conn: conn, r: bufio.NewReader(conn), commandTO: secondsOr(opts.CommandTimeoutSec, 60), maxLiteral: opts.MaxMessageBytes}
	// The greeting is the server's first move and healthy servers send it at
	// once, so it gets the connect budget rather than the command budget. A
	// server that accepts the connection and then says nothing — a per-account
	// connection limit, a middlebox, or a TLS port addressed in plaintext — is
	// then reported in seconds instead of holding a sync slot for a minute.
	start = time.Now()
	_ = conn.SetDeadline(start.Add(connectTO))
	greeting, err := s.readBoundedLine()
	if err != nil {
		conn.Close()
		return nil, s.failed(domain.StageGreeting, "", fmt.Errorf("imap greeting: %w", err), start)
	}
	// Every command sets its own deadline before writing (execRaw), so the
	// greeting's shorter one does not leak into the session.
	preAuth := strings.HasPrefix(greeting, "* PREAUTH")
	if strings.HasPrefix(greeting, "* BYE") {
		// Refused before any command — typically a connection limit.
		conn.Close()
		return nil, s.failed(domain.StageGreeting, "", &domain.InboundRejected{Code: domain.InboundResponseCode(greeting)}, start)
	}

	if opts.Security == domain.SecurityStartTLS {
		starttlsStart := time.Now()
		if _, err := s.exec("STARTTLS"); err != nil {
			conn.Close()
			return nil, fmt.Errorf("STARTTLS: %w", err)
		}
		// TLS is client-speaks-first: after the tagged OK that grants the upgrade
		// a conforming server sends nothing until it has seen the ClientHello. So
		// anything already sitting in the reader is plaintext the server pushed
		// ahead of the handshake — a STARTTLS command injection (CVE-2011-0411
		// and the 2021 "NO STARTTLS" survey), whose payload the upgrade below
		// would otherwise discard along with the old reader, leaving the session
		// to continue as if nothing had happened. Refusing is the safe verdict,
		// and it cannot cost a well-behaved server anything. The POP3 adapter
		// carries the same check on its STLS path.
		//
		// Best-effort by construction: only bytes that reached this buffer are
		// visible, so an injection still in flight in the kernel or on the wire
		// goes unseen. It narrows the window rather than closing it.
		//
		// The refusal names its own stage like every other failure in this
		// function: reported as a plain error it misses the errors.As in
		// syncDiagnosticStage and the operator is told the TCP connection
		// failed. Only the byte count goes in — never the bytes themselves.
		if n := s.r.Buffered(); n > 0 {
			conn.Close()
			refused := fmt.Errorf("STARTTLS: server sent %d bytes before TLS handshake", n)
			return nil, &domain.InboundError{Stage: domain.StageStartTLS, Command: "STARTTLS", Class: domain.ClassifyInbound(refused),
				Elapsed: time.Since(starttlsStart), Timeout: s.commandTO, Err: refused}
		}
		tconn := tls.Client(conn, tlsCfg)
		start = time.Now()
		if err := tconn.HandshakeContext(ctx); err != nil {
			conn.Close()
			return nil, &domain.InboundError{Stage: domain.StageTLS, Command: "STARTTLS", Class: domain.ClassifyInbound(err),
				Elapsed: time.Since(start), Timeout: s.commandTO, Err: fmt.Errorf("STARTTLS handshake: %w", err)}
		}
		s.conn = tconn
		s.r = bufio.NewReader(tconn)
	}

	// IMAP requires authentication before SELECT unless the server greeted
	// with PREAUTH. On offline maildrops "none" refers to transport, not auth.
	if !preAuth && opts.Username != "" {
		pass := ""
		if opts.Password != nil {
			pass = string(opts.Password.Reveal())
		}
		_, err := s.exec("LOGIN %s %s", quote(opts.Username), quote(pass))
		pass = ""
		_ = pass
		if err != nil {
			s.Close()
			// Only the server's refusal of these credentials is an auth
			// failure. A LOGIN that timed out, lost its connection, or was
			// refused for load says nothing about the password, and calling it
			// one parks the account in credential_error for good.
			var rejected *domain.InboundRejected
			if errors.As(err, &rejected) && !domain.TemporaryRefusal(rejected.Code) {
				return nil, &domain.AuthError{Err: fmt.Errorf("LOGIN rejected: %w", err)}
			}
			return nil, fmt.Errorf("LOGIN: %w", err)
		}
	}

	if err := s.selectInbox(); err != nil {
		s.Close()
		return nil, err
	}
	return s, nil
}

// connectFailure names the step a failed dial stopped at. With implicit TLS
// the dialer runs TCP and the handshake as one call; a TLS error type tells
// the two apart.
func connectFailure(err error, elapsed, timeout time.Duration) error {
	stage := domain.StageTCPConnect
	switch domain.ClassifyInbound(err) {
	case "tls_certificate", "tls_handshake":
		stage = domain.StageTLS
	}
	return &domain.InboundError{Stage: stage, Class: domain.ClassifyInbound(err), Elapsed: elapsed, Timeout: timeout, Err: fmt.Errorf("imap connect: %w", err)}
}

type session struct {
	conn        net.Conn
	r           *bufio.Reader
	commandTO   time.Duration
	maxLiteral  int64 // per-literal buffer cap (0 = unlimited); OOM guard
	tagN        int
	uidValidity string
	exists      int
	index       []domain.RemoteMessage
	indexed     bool
	deleted     bool
	literals    []string // literal payloads read during the last exec, in order
	broken      error    // set once the stream can no longer be trusted
}

// literalMargin is the slack allowed over MaxMessageBytes before a literal is
// refused, so a legitimate at-limit message still fetches with its envelope and
// header framing.
const literalMargin = 1 << 20

// resyncDrainFactor bounds how many bytes a refused literal may cost to
// discard, as a multiple of the size at which a literal is refused. Within that
// budget, dropping the body costs a moment and the ingest loop can carry on with
// the rest of the mailbox over the same session. Beyond it the announced length
// is no longer plausibly a message the server is really sending, and a bogus
// length announces bytes that never arrive and would only block until the
// command deadline, so the session is abandoned instead of drained. Deriving the
// budget from the refusal threshold keeps the drain path reachable at every
// configured MaxMessageBytes rather than only at small ones.
const resyncDrainFactor = 4

// drainChunk is how much of a refused literal is discarded between deadline
// refreshes, so a slow but live server is not cut off mid-drain.
// the next protocol line is read where the server believes the response
// continues. A length too large to drain — or a drain that fails part way —
// leaves the stream at an unknown offset, so the session is abandoned instead.
func (s *session) discardLiteral(n int64) error {
	if budget := s.resyncBudget(); n > budget {
		return s.abandon(fmt.Errorf("%w: %d-byte literal exceeds the %d-byte resync budget", errUnframed, n, budget))
	}
	for remaining := n; remaining > 0; {
		chunk := remaining
		if chunk > drainChunk {
			chunk = drainChunk
		}
		s.deadline()
		got, err := io.CopyN(io.Discard, s.r, chunk)
		if err != nil {
			return s.abandon(fmt.Errorf("%w: discarding a %d-byte literal: %w", errUnframed, n, err))
		}
		remaining -= got
	}
	return nil
}

// abandon closes the connection and records why every later command fails.
func (s *session) abandon(err error) error {
	s.broken = err
	s.conn.Close()
	return err
}

func (s *session) selectInbox() error {
	lines, err := s.exec("SELECT INBOX")
	if err != nil {
		return fmt.Errorf("SELECT INBOX: %w", err)
	}
	for _, l := range lines {
		if m := reExist.FindStringSubmatch(l); m != nil {
			s.exists, _ = strconv.Atoi(m[1])
		}
		if m := reValid.FindStringSubmatch(l); m != nil {
			s.uidValidity = m[1]
		}
	}
	return nil
}

// ensureIndex enumerates the mailbox once (UID + size per sequence number) and
// caches it. The stable per-message ID is "UIDVALIDITY.UID", which the sync
// layer stores as the dedup checkpoint.
// enumerateBatch bounds how many messages are enumerated per FETCH so the
// whole-mailbox metadata response is never buffered in memory at once — a
// single FETCH 1:N over a large mailbox was a primary OOM (pod restart) source.
const enumerateBatch = 2000

func (s *session) ensureIndex() error {
	if s.indexed {
		return nil
	}
	s.indexed = true
	if s.exists == 0 {
		return nil
	}
	for start := 1; start <= s.exists; start += enumerateBatch {
		end := start + enumerateBatch - 1
		if end > s.exists {
			end = s.exists
		}
		lines, err := s.exec("FETCH %d:%d (UID RFC822.SIZE)", start, end)
		if err != nil {
			return err
		}
		for _, l := range lines {
			fm := reFetch.FindStringSubmatch(l)
			if fm == nil {
				continue
			}
			seq, _ := strconv.Atoi(fm[1])
			rm := domain.RemoteMessage{Number: seq}
			if m := reUID.FindStringSubmatch(l); m != nil {
				rm.UIDL = s.uidValidity + "." + m[1]
			}
			if m := reSize.FindStringSubmatch(l); m != nil {
				rm.Size, _ = strconv.ParseInt(m[1], 10, 64)
			}
			s.index = append(s.index, rm)
		}
	}
	return nil
}

func (s *session) UIDL(ctx context.Context) ([]domain.RemoteMessage, error) {
	if err := s.ensureIndex(); err != nil {
		return nil, err
	}
	return s.index, nil
}

func (s *session) List(ctx context.Context) ([]domain.RemoteMessage, error) {
	if err := s.ensureIndex(); err != nil {
		return nil, err
	}
	return s.index, nil
}

func (s *session) Retrieve(ctx context.Context, number int) (io.ReadCloser, error) {
	if _, err := s.exec("FETCH %d (BODY.PEEK[])", number); err != nil {
		return nil, err
	}
	return s.firstLiteral()
}

func (s *session) Top(ctx context.Context, number, lines int) (io.ReadCloser, error) {
	if _, err := s.exec("FETCH %d (BODY.PEEK[HEADER])", number); err != nil {
		return nil, err
	}
	return s.firstLiteral()
}

// firstLiteral returns the message bytes captured by the preceding FETCH.
func (s *session) firstLiteral() (io.ReadCloser, error) {
	if len(s.literals) == 0 {
		return nil, fmt.Errorf("no message literal in FETCH response")
	}
	lit := s.literals[0]
	s.literals = nil
	return io.NopCloser(strings.NewReader(lit)), nil
}

func (s *session) Delete(ctx context.Context, number int) error {
	if _, err := s.exec(`STORE %d +FLAGS (\Deleted)`, number); err != nil {
		return err
	}
	s.deleted = true
	return nil
}

func (s *session) Quit(ctx context.Context) error {
	if s.deleted {
		_, _ = s.exec("EXPUNGE")
	}
	_, err := s.exec("LOGOUT")
	s.conn.Close()
	return err
}

func (s *session) Close() error { return s.conn.Close() }

// MessageCount reports EXISTS from the last SELECT.
func (s *session) MessageCount() int { return s.exists }

// ListMailboxes returns the list of IMAP folder names available (§P1 IMAP 폴더 동기화).
func (s *session) ListMailboxes(ctx context.Context) ([]string, error) {
	lines, err := s.exec(`LIST "" "*"`)
	if err != nil {
		return nil, fmt.Errorf("LIST mailboxes: %w", err)
	}
	var mailboxes []string
	reList := regexp.MustCompile(`^\* LIST \(.*\) ".*" "?([^"]+)"?`)
	for _, l := range lines {
		if m := reList.FindStringSubmatch(l); m != nil {
			mailboxes = append(mailboxes, m[1])
		}
	}
	return mailboxes, nil
}

// SelectMailbox selects a specific folder/mailbox (e.g., "INBOX", "Sent", "Drafts").
func (s *session) SelectMailbox(name string) error {
	lines, err := s.exec("SELECT %s", quote(name))
	if err != nil {
		return fmt.Errorf("SELECT %s: %w", name, err)
	}
	s.exists = 0
	s.index = nil
	s.indexed = false
	for _, l := range lines {
		if m := reExist.FindStringSubmatch(l); m != nil {
			s.exists, _ = strconv.Atoi(m[1])
		}
		if m := reValid.FindStringSubmatch(l); m != nil {
			s.uidValidity = m[1]
		}
	}
	return nil
}

// FetchFlags fetches IMAP flags (e.g. \Seen, \Flagged, \Draft) for a sequence number.
func (s *session) FetchFlags(ctx context.Context, number int) ([]string, error) {
	lines, err := s.exec("FETCH %d (FLAGS)", number)
	if err != nil {
		return nil, err
	}
	reFlags := regexp.MustCompile(`FLAGS \(([^)]*)\)`)
	var flags []string
	for _, l := range lines {
		if m := reFlags.FindStringSubmatch(l); m != nil {
			for _, f := range strings.Fields(m[1]) {
				flags = append(flags, f)
			}
		}
	}
	return flags, nil
}

// readLineNoReset reads one CRLF-terminated line WITHOUT resetting the
// connection deadline (readLine resets it to commandTO on every call, which
// would defeat the long IDLE window). The caller manages the deadline. The
// maxLineBytes bound matters most here: the deadline this path runs under is the
// 28-minute re-idle window, so an unbounded line would buffer for that long.
func (s *session) readLineNoReset() (string, error) {
	return s.readBoundedLine()
}

// Idle issues the RFC 2177 IDLE command and blocks until the server reports
// mailbox activity (EXISTS/RECENT/EXPUNGE), the ~28-minute re-idle window
// elapses (returns nil so the caller re-idles), or ctx is cancelled. It is
// self-contained: a single watcher goroutine pokes the read deadline on
// cancellation and is always joined, so no reader goroutine is leaked across
// successive Idle calls (§P1 IMAP IDLE).
func (s *session) Idle(ctx context.Context) error {
	if s.broken != nil {
		return s.broken
	}
	s.tagN++
	tag := fmt.Sprintf("a%d", s.tagN)

	_ = s.conn.SetDeadline(time.Now().Add(30 * time.Second))
	if _, err := fmt.Fprintf(s.conn, "%s IDLE\r\n", tag); err != nil {
		return err
	}
	line, err := s.readLineNoReset()
	if err != nil {
		return err
	}
	if !strings.HasPrefix(line, "+") {
		return fmt.Errorf("IDLE rejected: %s", line)
	}

	stop := make(chan struct{})
	defer close(stop)
	go func() {
		select {
		case <-ctx.Done():
			_ = s.conn.SetDeadline(time.Now()) // unblock the pending read
		case <-stop:
		}
	}()

	// Terminate the IDLE cleanly and drain to the tagged completion so the
	// session is reusable for the next command / re-idle.
	defer func() {
		_ = s.conn.SetDeadline(time.Now().Add(10 * time.Second))
		_, _ = fmt.Fprintf(s.conn, "DONE\r\n")
		for {
			l, derr := s.readLineNoReset()
			if derr != nil || strings.HasPrefix(l, tag+" ") {
				break
			}
		}
	}()

	// Re-IDLE before servers' 30-minute limit; return nil on the timeout so the
	// caller starts a fresh IDLE.
	_ = s.conn.SetDeadline(time.Now().Add(28 * time.Minute))
	for {
		if ctx.Err() != nil {
			return ctx.Err()
		}
		l, err := s.readLineNoReset()
		if err != nil {
			if ctx.Err() != nil {
				return ctx.Err()
			}
			if ne, ok := err.(net.Error); ok && ne.Timeout() {
				return nil // periodic re-idle
			}
			return err
		}
		if strings.Contains(l, "EXISTS") || strings.Contains(l, "RECENT") || strings.Contains(l, "EXPUNGE") {
			return nil
		}
	}
}

var _ domain.IdleCapable = (*session)(nil)

// quote wraps an IMAP astring in double quotes, escaping backslash and quote.
func quote(s string) string {
	s = strings.ReplaceAll(s, `\`, `\\`)
	s = strings.ReplaceAll(s, `"`, `\"`)
	return `"` + s + `"`
}

func secondsOr(v, def int) time.Duration {
	if v <= 0 {
		v = def
	}
	return time.Duration(v) * time.Second
}

// commandVerb is the protocol verb of a command format ("LOGIN %s %s" →
// "LOGIN", "UID FETCH …" → "UID FETCH"). Arguments never leave the adapter:
// LOGIN's carry the password.
func commandVerb(format string) string {
	fields := strings.Fields(format)
	if len(fields) == 0 {
		return ""
	}
	verb := strings.ToUpper(fields[0])
	if verb == "UID" && len(fields) > 1 {
		verb += " " + strings.ToUpper(fields[1])
	}
	return verb
}

// commandStage places a command in the session's life for diagnostics.
func commandStage(format string) string {
	switch verb := commandVerb(format); {
	case verb == "LOGIN" || verb == "AUTHENTICATE":
		return domain.StageLogin
	case verb == "SELECT" || verb == "EXAMINE":
		return domain.StageSelect
	case verb == "STARTTLS":
		return domain.StageStartTLS
	case verb == "LIST":
		return domain.StageList
	case verb == "IDLE":
		return domain.StageIdle
	case verb == "LOGOUT":
		return domain.StageLogout
	case strings.Contains(format, "RFC822.SIZE"):
		return domain.StageEnumerate
	default:
		return domain.StageFetch
	}
}

// failed records where the session broke, once.
func (s *session) failed(stage, verb string, err error, start time.Time) error {
	return domain.WrapInbound(stage, verb, err, time.Since(start), s.commandTO)
}
	s.deadline()
	if err := s.text.PrintfLine(format, args...); err != nil {
		return "", domain.WrapInbound(stage, verb, err, time.Since(start), s.commandTO)
	}
	line, err := s.readResponse()
	if err != nil {
		return "", domain.WrapInbound(stage, verb, err, time.Since(start), s.commandTO)
	}
	return line, nil
}

// readList collects a multi-line response up to its "." terminator, bounded by
// maxListBytes so an unterminated response cannot hold the session for ever.
func (s *session) readList() ([]string, error) {
	var lines []string
	var charged int64
	for {
		s.deadline()
		line, err := s.text.ReadLine()
		if err != nil {
			return nil, err
		}
		if line == "." {
			return lines, nil
		}
		charged += int64(len(line)) + listLineOverhead
		if charged > maxListBytes {
			// The rest of the response is still on the wire and its length is
			// unknown, so the offset the next command would read at is
			// unknowable: discard the session rather than let a later command
			// mistake those bytes for its own reply.
			s.conn.Close()
			return nil, fmt.Errorf("pop3 multi-line response exceeds %d bytes", int64(maxListBytes))
		}
		lines = append(lines, strings.TrimPrefix(line, "."))
	}
}

func (s *session) List(ctx context.Context) ([]domain.RemoteMessage, error) {
	if _, err := s.cmd("LIST"); err != nil {
		return nil, err
	}
	listStart := time.Now()
	lines, err := s.readList()
	if err != nil {
		return nil, domain.WrapInbound(domain.StageEnumerate, "LIST", err, time.Since(listStart), s.commandTO)
	}
	var out []domain.RemoteMessage
	for _, l := range lines {
		var n int
		var size int64
		if _, err := fmt.Sscanf(l, "%d %d", &n, &size); err == nil {
			out = append(out, domain.RemoteMessage{Number: n, Size: size})
		}
	}
	return out, nil
}

func (s *session) UIDL(ctx context.Context) ([]domain.RemoteMessage, error) {
	if _, err := s.cmd("UIDL"); err != nil {
		return nil, err // caller falls back to LIST + content hash (POP-005)
	}
	listStart := time.Now()
	lines, err := s.readList()
	if err != nil {
		return nil, domain.WrapInbound(domain.StageEnumerate, "UIDL", err, time.Since(listStart), s.commandTO)
	}
	var out []domain.RemoteMessage
	for _, l := range lines {
		parts := strings.SplitN(strings.TrimSpace(l), " ", 2)
		if len(parts) != 2 {
			continue
		}
		n, err := strconv.Atoi(parts[0])
		if err != nil {
			continue
		}
		out = append(out, domain.RemoteMessage{Number: n, UIDL: strings.TrimSpace(parts[1])})
	}
	return out, nil
}

// retrBody reads a multi-line response body with dot-unstuffing.
func (s *session) retrBody() (io.ReadCloser, error) {
	var buf bytes.Buffer
	for {
		s.deadline()
		line, err := s.text.ReadLineBytes()
		if err != nil {
			return nil, err
		}
		if len(line) == 1 && line[0] == '.' {
			break
		}
		if len(line) > 1 && line[0] == '.' {
			line = line[1:]
		}
		buf.Write(line)
		buf.WriteString("\r\n")
	}
	return io.NopCloser(&buf), nil
}

func (s *session) Retrieve(ctx context.Context, number int) (io.ReadCloser, error) {
	if _, err := s.cmd("RETR %d", number); err != nil {
		return nil, err
	}
	// retrBody sets the command deadline itself, so the wait starts here:
	// reporting 0 would make syncTiming print only the limit and lose the
	// slow-server/cut-connection distinction the fetch diagnostic exists for.
	bodyStart := time.Now()
	body, err := s.retrBody()
	if err != nil {
		return nil, domain.WrapInbound(domain.StageFetch, "RETR", err, time.Since(bodyStart), s.commandTO)
	}
	return body, nil
}

func (s *session) Top(ctx context.Context, number, lines int) (io.ReadCloser, error) {
	if _, err := s.cmd("TOP %d %d", number, lines); err != nil {
		return nil, err
	}
	bodyStart := time.Now()
	body, err := s.retrBody()
	if err != nil {
